// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0);
        vm.assume(uint160(actor) > 10);

        // lock in a guess at block B; target block is B+1
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(bytes32(0));

        uint256 targetBlock = block.number - 1; // block.number is now B+1
        vm.roll(block.number + 1); // now block.number == B+2 > B+1, and blockhash(B+1) is reachable

        bytes32 answer = blockhash(targetBlock);
        if (answer != bytes32(0)) {
            // overwrite the guess with the true blockhash via a fresh full cycle:
            // settle resets the slot, then lock again with the right hash
            vm.prank(actor);
            c.settle(); // loses (guess was 0), resets state

            vm.deal(actor, 1 ether);
            vm.prank(actor);
            c.lockInGuess{value: 1 ether}(answer);
            vm.roll(block.number + 1);

            vm.prank(actor);
            c.settle();

            // winner must drain the contract completely (2 ether payout)
            assertTrue(address(c).balance == 0);
        } else {
            // fallback admissible path: even a losing settle must keep the
            // contract whole but at most its own 2 ether (still holds for P,
            // broken by M whenever the guess wins)
            assertTrue(true);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(uint256 n, address actor) public {
        // admissible domain: plain EOAs other than the contract itself
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0);
        n = bound(n, 1, 200);

        // create block n+1, step back to n, and learn the (deterministic) hash
        // of block n+1 so the guess can be made a guaranteed winner.
        vm.roll(n + 1);
        vm.roll(n);
        bytes32 answer = blockhash(n + 1);

        // actor funds itself and locks in the winning guess at block n,
        // so the guess block is n+1 and c now holds 2 ether.
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(answer);

        // advance past the guess block and settle.
        vm.roll(n + 2);
        bool ok;
        vm.prank(actor);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // RULE: any successful settle leaves c with 2 ether (guess lost, no
        // payout) or 0 ether (guess won, the full 2-ether prize is paid out).
        // The reference always satisfies this; the mutant pays only 1 ether on
        // a win, leaving 1 ether stuck, so the fuzzer-distinguishable win case
        // breaks it.
        assertTrue(!ok || address(c).balance == 0 || address(c).balance == 2 ether);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function testLockInGuess(bytes32 h, uint v) public {
        require(v != 1 ether);
        require(address(this).balance >= v);
        bool reverted;
        try c.lockInGuess{value: v}(h) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test() public {
        // No guess has been locked in; settle must revert on the correct contract.
        bool reverted = false;
        // read-only probe not needed; perform the deciding call
        bytes memory data = new bytes(0);
        (bool ok, ) = address(c).call(data);
        reverted = !ok;
        assert(reverted);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount != 1 ether);
        require(address(this).balance >= amount);
        bool reverted;
        try c.lockInGuess{value: amount}(keccak256(abi.encodePacked(amount))) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        try c.settle() { reverted = false; } catch { reverted = true; }
        assert(reverted == true);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 g, uint a, uint b) public payable {
        require(a != 1 ether);
        require(address(this).balance >= b);
        bool reverted1;
        try c.lockInGuess{value: a}(g) { reverted1 = false; } catch { reverted1 = true; }
        bool reverted2;
        try c.lockInGuess{value: b}(g) { reverted2 = false; } catch { reverted2 = true; }
        assert(b != 1 ether || !reverted2);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        // Precondition: the test contract (the msg.sender of the call below)
        // has never called lockInGuess on c, so guesses[address(this)].block == 0.
        // settle() from an account with no locked-in guess must revert in P;
        // the mutant lets it succeed (its inverted require passes).
        bool reverted;
        try c.settle() { reverted = false; } catch { reverted = true; }   // boundary
        assert(reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 h, uint amount) public payable {
        require(address(this).balance >= amount);
        require(amount == 1 ether);
        bool r1;
        try c.settle() { r1 = false; } catch { r1 = true; }
        c.lockInGuess{value: amount}(h);
        bool r2;
        try c.settle() { r2 = false; } catch { r2 = true; }
        assert(r1 && r2);
    }
    receive() external payable {}
}
